import java.util.*;

class MovieRentingSystem {
    private final Map<Long, Integer> priceByCopy = new HashMap<>();
    private final Map<Integer, TreeSet<Copy>> availableByMovie = new HashMap<>();
    private final TreeSet<Copy> rented = new TreeSet<>();

    public MovieRentingSystem(int n, int[][] entries) {
        for (int[] entry : entries) {
            int shop = entry[0];
            int movie = entry[1];
            int price = entry[2];
            Copy copy = new Copy(price, shop, movie);
            priceByCopy.put(key(shop, movie), price);
            availableByMovie.computeIfAbsent(movie, ignored -> new TreeSet<>()).add(copy);
        }
    }

    public List<Integer> search(int movie) {
        List<Integer> result = new ArrayList<>();
        TreeSet<Copy> copies = availableByMovie.get(movie);
        if (copies == null) {
            return result;
        }
        for (Copy copy : copies) {
            result.add(copy.shop);
            if (result.size() == 5) {
                break;
            }
        }
        return result;
    }

    public void rent(int shop, int movie) {
        int price = priceByCopy.get(key(shop, movie));
        Copy copy = new Copy(price, shop, movie);
        availableByMovie.get(movie).remove(copy);
        rented.add(copy);
    }

    public void drop(int shop, int movie) {
        int price = priceByCopy.get(key(shop, movie));
        Copy copy = new Copy(price, shop, movie);
        rented.remove(copy);
        availableByMovie.get(movie).add(copy);
    }

    public List<List<Integer>> report() {
        List<List<Integer>> result = new ArrayList<>();
        for (Copy copy : rented) {
            result.add(Arrays.asList(copy.shop, copy.movie));
            if (result.size() == 5) {
                break;
            }
        }
        return result;
    }

    private static long key(int shop, int movie) {
        return (((long) shop) << 32) ^ movie;
    }

    private static final class Copy implements Comparable<Copy> {
        final int price;
        final int shop;
        final int movie;

        Copy(int price, int shop, int movie) {
            this.price = price;
            this.shop = shop;
            this.movie = movie;
        }

        public int compareTo(Copy other) {
            if (price != other.price) {
                return Integer.compare(price, other.price);
            }
            if (shop != other.shop) {
                return Integer.compare(shop, other.shop);
            }
            return Integer.compare(movie, other.movie);
        }
    }
}

