class MovieRentingSystem {
    private final Map<Long, Integer> priceByCopy = new HashMap<>();
    private final Map<Integer, List<Integer>> copiesByMovie = new HashMap<>();
    private final Set<Long> rented = new HashSet<>();

    public MovieRentingSystem(int n, int[][] entries) {
        for (int[] entry : entries) {
            int shop = entry[0];
            int movie = entry[1];
            int price = entry[2];
            priceByCopy.put(key(shop, movie), price);
            copiesByMovie.computeIfAbsent(movie, ignored -> new ArrayList<>()).add(shop);
        }
    }

    public List<Integer> search(int movie) {
        List<int[]> available = new ArrayList<>();
        for (int shop : copiesByMovie.getOrDefault(movie, Collections.emptyList())) {
            long copyKey = key(shop, movie);
            if (!rented.contains(copyKey)) {
                available.add(new int[] {priceByCopy.get(copyKey), shop});
            }
        }
        available.sort((a, b) -> a[0] != b[0]
                ? Integer.compare(a[0], b[0])
                : Integer.compare(a[1], b[1]));
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < Math.min(5, available.size()); i++) {
            result.add(available.get(i)[1]);
        }
        return result;
    }

    public void rent(int shop, int movie) {
        rented.add(key(shop, movie));
    }

    public void drop(int shop, int movie) {
        rented.remove(key(shop, movie));
    }

    public List<List<Integer>> report() {
        List<long[]> rentedCopies = new ArrayList<>();
        for (Long copyKey : rented) {
            int shop = shopFromKey(copyKey);
            int movie = movieFromKey(copyKey);
            rentedCopies.add(new long[] {priceByCopy.get(copyKey), shop, movie});
        }
        Collections.sort(rentedCopies, (a, b) -> {
            if (a[0] != b[0]) {
                return Long.compare(a[0], b[0]);
            }
            if (a[1] != b[1]) {
                return Long.compare(a[1], b[1]);
            }
            return Long.compare(a[2], b[2]);
        });
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < Math.min(5, rentedCopies.size()); i++) {
            long[] copy = rentedCopies.get(i);
            result.add(Arrays.asList((int) copy[1], (int) copy[2]));
        }
        return result;
    }

    private static long key(int shop, int movie) {
        return (((long) shop) << 32) ^ movie;
    }

    private static int shopFromKey(long key) {
        return (int) (key >>> 32);
    }

    private static int movieFromKey(long key) {
        return (int) key;
    }
}

