class MovieRentingSystem {
    private final Map<Long, Integer> priceByCopy = new HashMap<>();
    private final Map<Integer, PriorityQueue<HeapCopy>> availableByMovie = new HashMap<>();
    private final PriorityQueue<HeapCopy> rentedHeap = new PriorityQueue<>();
    private final Map<Long, Boolean> rentedState = new HashMap<>();
    private final Map<Long, Integer> availableVersion = new HashMap<>();
    private final Map<Long, Integer> rentedVersion = new HashMap<>();

    public MovieRentingSystem(int n, int[][] entries) {
        for (int[] entry : entries) {
            int shop = entry[0];
            int movie = entry[1];
            int price = entry[2];
            long copyKey = key(shop, movie);
            priceByCopy.put(copyKey, price);
            rentedState.put(copyKey, false);
            availableVersion.put(copyKey, 0);
            rentedVersion.put(copyKey, 0);
            availableByMovie.computeIfAbsent(movie, ignored -> new PriorityQueue<>())
                    .offer(new HeapCopy(price, shop, movie, 0));
        }
    }

    public List<Integer> search(int movie) {
        PriorityQueue<HeapCopy> heap = availableByMovie.get(movie);
        List<Integer> result = new ArrayList<>();
        if (heap == null) {
            return result;
        }
        List<HeapCopy> keep = new ArrayList<>();
        while (!heap.isEmpty() && result.size() < 5) {
            HeapCopy copy = heap.poll();
            if (!isAvailableHeapEntryLive(copy)) {
                continue;
            }
            result.add(copy.shop);
            keep.add(copy);
        }
        for (HeapCopy copy : keep) {
            heap.offer(copy);
        }
        return result;
    }

    public void rent(int shop, int movie) {
        long copyKey = key(shop, movie);
        rentedState.put(copyKey, true);
        int version = rentedVersion.merge(copyKey, 1, Integer::sum);
        int price = priceByCopy.get(copyKey);
        rentedHeap.offer(new HeapCopy(price, shop, movie, version));
    }

    public void drop(int shop, int movie) {
        long copyKey = key(shop, movie);
        rentedState.put(copyKey, false);
        int version = availableVersion.merge(copyKey, 1, Integer::sum);
        int price = priceByCopy.get(copyKey);
        availableByMovie.get(movie).offer(new HeapCopy(price, shop, movie, version));
    }

    public List<List<Integer>> report() {
        List<List<Integer>> result = new ArrayList<>();
        List<HeapCopy> keep = new ArrayList<>();
        while (!rentedHeap.isEmpty() && result.size() < 5) {
            HeapCopy copy = rentedHeap.poll();
            if (!isRentedHeapEntryLive(copy)) {
                continue;
            }
            result.add(Arrays.asList(copy.shop, copy.movie));
            keep.add(copy);
        }
        for (HeapCopy copy : keep) {
            rentedHeap.offer(copy);
        }
        return result;
    }

    private boolean isAvailableHeapEntryLive(HeapCopy copy) {
        long copyKey = key(copy.shop, copy.movie);
        return !rentedState.get(copyKey) && availableVersion.get(copyKey) == copy.version;
    }

    private boolean isRentedHeapEntryLive(HeapCopy copy) {
        long copyKey = key(copy.shop, copy.movie);
        return rentedState.get(copyKey) && rentedVersion.get(copyKey) == copy.version;
    }

    private static long key(int shop, int movie) {
        return (((long) shop) << 32) ^ movie;
    }

    private static final class HeapCopy implements Comparable<HeapCopy> {
        final int price;
        final int shop;
        final int movie;
        final int version;

        HeapCopy(int price, int shop, int movie, int version) {
            this.price = price;
            this.shop = shop;
            this.movie = movie;
            this.version = version;
        }

        public int compareTo(HeapCopy other) {
            if (price != other.price) {
                return Integer.compare(price, other.price);
            }
            if (shop != other.shop) {
                return Integer.compare(shop, other.shop);
            }
            return Integer.compare(movie, other.movie);
        }
    }
}

