class MovieRentingSystem {
    private final Map<Long, Integer> priceByCopy = new HashMap<>();
    private final Map<Integer, TreeMap<Integer, TreeSet<Integer>>> availableByMovie = new HashMap<>();
    private final TreeMap<Integer, TreeSet<Long>> rentedByPrice = new TreeMap<>();

    public MovieRentingSystem(int n, int[][] entries) {
        for (int[] entry : entries) {
            int shop = entry[0];
            int movie = entry[1];
            int price = entry[2];
            priceByCopy.put(key(shop, movie), price);
            addAvailableCopy(shop, movie, price);
        }
    }

    public List<Integer> search(int movie) {
        List<Integer> result = new ArrayList<>();
        TreeMap<Integer, TreeSet<Integer>> byPrice = availableByMovie.get(movie);
        if (byPrice == null) {
            return result;
        }
        for (TreeSet<Integer> shops : byPrice.values()) {
            for (int shop : shops) {
                result.add(shop);
                if (result.size() == 5) {
                    return result;
                }
            }
        }
        return result;
    }

    public void rent(int shop, int movie) {
        int price = priceByCopy.get(key(shop, movie));
        removeAvailableCopy(shop, movie, price);
        rentedByPrice.computeIfAbsent(price, ignored -> new TreeSet<>()).add(pair(shop, movie));
    }

    public void drop(int shop, int movie) {
        int price = priceByCopy.get(key(shop, movie));
        TreeSet<Long> rentedAtPrice = rentedByPrice.get(price);
        rentedAtPrice.remove(pair(shop, movie));
        if (rentedAtPrice.isEmpty()) {
            rentedByPrice.remove(price);
        }
        addAvailableCopy(shop, movie, price);
    }

    public List<List<Integer>> report() {
        List<List<Integer>> result = new ArrayList<>();
        for (TreeSet<Long> pairs : rentedByPrice.values()) {
            for (long pair : pairs) {
                result.add(Arrays.asList(shopFromPair(pair), movieFromPair(pair)));
                if (result.size() == 5) {
                    return result;
                }
            }
        }
        return result;
    }

    private void addAvailableCopy(int shop, int movie, int price) {
        availableByMovie.computeIfAbsent(movie, ignored -> new TreeMap<>())
                .computeIfAbsent(price, ignored -> new TreeSet<>())
                .add(shop);
    }

    private void removeAvailableCopy(int shop, int movie, int price) {
        TreeMap<Integer, TreeSet<Integer>> byPrice = availableByMovie.get(movie);
        TreeSet<Integer> shops = byPrice.get(price);
        shops.remove(shop);
        if (shops.isEmpty()) {
            byPrice.remove(price);
        }
        if (byPrice.isEmpty()) {
            availableByMovie.remove(movie);
        }
    }

    private static long key(int shop, int movie) {
        return (((long) shop) << 32) ^ movie;
    }

    private static long pair(int shop, int movie) {
        return (((long) shop) << 32) ^ movie;
    }

    private static int shopFromPair(long pair) {
        return (int) (pair >>> 32);
    }

    private static int movieFromPair(long pair) {
        return (int) pair;
    }
}
